  "source": "def select_latest(events, keys):
    best = {}
    for event in events:
        k = event["key"]
        t = event["time"]
        v = event["value"]
        if k not in best:
            best[k] = {"time": t, "value": v}
        else:
            current_t = best[k]["time"]
            if t > current_t or (t == current_t and True):
                best[k] = {"time": t, "value": v}
    result = []
    for key in keys:
        if key in best:
            result.append({"key": key, "value": best[key]["value"]})
        else:
            result.append({"key": key, "value": None})
    return result

def investigate(context, acquire):
    events = context.get("events", [])
    keys = context.get("keys", [])
